import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import type {ReactNode} from 'react';
import {configure} from '@gravity-ui/uikit';
import {formatMessage, LANGUAGES} from './translations';
import type {Language, TranslationKey} from './translations';

const STORAGE_KEY = 'app.language';

function isLanguage(value: unknown): value is Language {
  return typeof value === 'string' && (LANGUAGES as string[]).includes(value);
}

/**
 * Initial language priority: saved choice → browser language → English.
 */
function detectInitialLanguage(): Language {
  try {
    const saved = window.localStorage.getItem(STORAGE_KEY);
    if (isLanguage(saved)) return saved;
  } catch {
    // localStorage unavailable (private mode, SSR) — fall through.
  }
  return navigator.language.toLowerCase().startsWith('ru') ? 'ru' : 'en';
}

export interface LanguageContextValue {
  language: Language;
  setLanguage: (language: Language) => void;
  toggleLanguage: () => void;
  /** Translate a key, substituting `{placeholder}` params when given. */
  t: (key: TranslationKey, params?: Record<string, string | number>) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({children}: {children: ReactNode}) {
  const [language, setLanguage] = useState<Language>(detectInitialLanguage);

  // Keep side effects in sync with the active language:
  // <html lang> for accessibility/SEO, Gravity UI's own internal strings,
  // and the persisted choice.
  useEffect(() => {
    document.documentElement.lang = language;
    configure({lang: language});
    try {
      window.localStorage.setItem(STORAGE_KEY, language);
    } catch {
      // Persisting is best-effort.
    }
  }, [language]);

  const toggleLanguage = useCallback(() => {
    setLanguage((prev) => (prev === 'en' ? 'ru' : 'en'));
  }, []);

  const t = useCallback(
    (key: TranslationKey, params?: Record<string, string | number>) =>
      formatMessage(language, key, params),
    [language],
  );

  const value = useMemo<LanguageContextValue>(
    () => ({language, setLanguage, toggleLanguage, t}),
    [language, toggleLanguage, t],
  );

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage(): LanguageContextValue {
  const ctx = useContext(LanguageContext);
  if (!ctx) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return ctx;
}

