import {useState} from 'react';
import {Button, Card, Progress, Text} from '@gravity-ui/uikit';
import {useLanguage} from './i18n/LanguageContext';
import {LanguageSwitcher} from './components/LanguageSwitcher';

const SPRINT_DONE = 18;
const SPRINT_TOTAL = 24;

export function App() {
  const {t} = useLanguage();
  const [notifications, setNotifications] = useState<string[]>([
    t('notificationReview', {name: 'Anna'}),
    t('notificationDeploy'),
  ]);

  return (
    <div style={{maxWidth: 720, margin: '0 auto', padding: 24}}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: 16,
          flexWrap: 'wrap',
          marginBottom: 24,
        }}
      >
        <div>
          <Text variant="header-1">{t('appTitle')}</Text>
          <div>
            <Text variant="body-2" color="secondary">
              {t('appSubtitle')}
            </Text>
          </div>
        </div>
        <LanguageSwitcher />
      </header>

      <Card style={{padding: 20, marginBottom: 16}}>
        <Text variant="subheader-2">{t('greeting', {name: 'Alex'})}</Text>
        <div style={{marginBottom: 16}}>
          <Text variant="body-2" color="secondary">
            {t('welcomeBack')}
          </Text>
        </div>
        <div style={{display: 'flex', gap: 32, flexWrap: 'wrap'}}>
          <Stat value={5} label={t('statsActiveProjects')} />
          <Stat value={12} label={t('statsOpenTasks')} />
          <Stat value={7} label={t('statsDoneThisWeek')} />
        </div>
      </Card>

      <Card style={{padding: 20, marginBottom: 16}}>
        <div style={{marginBottom: 8}}>
          <Text variant="subheader-2">{t('progressTitle')}</Text>
        </div>
        <Progress value={(SPRINT_DONE / SPRINT_TOTAL) * 100} />
        <div style={{marginTop: 8}}>
          <Text variant="body-2" color="secondary">
            {t('progressValue', {done: SPRINT_DONE, total: SPRINT_TOTAL})}
          </Text>
        </div>
      </Card>

      <Card style={{padding: 20, marginBottom: 16}}>
        <div style={{marginBottom: 8}}>
          <Text variant="subheader-2">{t('notificationsTitle')}</Text>
        </div>
        {notifications.length === 0 ? (
          <Text variant="body-2" color="secondary">
            {t('notificationsEmpty')}
          </Text>
        ) : (
          <ul style={{margin: 0, paddingLeft: 20}}>
            {notifications.map((item) => (
              <li key={item}>
                <Text variant="body-2">{item}</Text>
              </li>
            ))}
          </ul>
        )}
        <div style={{display: 'flex', gap: 12, marginTop: 12}}>
          <Button view="action">{t('createTask')}</Button>
          <Button view="flat" onClick={() => setNotifications([])}>
            {t('markAllRead')}
          </Button>
        </div>
      </Card>

      <Text variant="caption-2" color="hint">
        {t('footerNote')}
      </Text>
    </div>
  );
}

function Stat({value, label}: {value: number; label: string}) {
  return (
    <div>
      <Text variant="display-2">{value}</Text>
      <div>
        <Text variant="body-2" color="secondary">
          {label}
        </Text>
      </div>
    </div>
  );
}

