import {useState} from 'react';
import {Button, Card, Progress, Text} from '@gravity-ui/uikit';
import {useLanguage} from './i18n/LanguageContext';
import {LanguageSwitcher} from './components/LanguageSwitcher';

const USER_NAME = 'Anna';
const TASKS_DONE = 18;
const TASKS_TOTAL = 24;

export function App() {
  const {t} = useLanguage();
  const [notificationsRead, setNotificationsRead] = useState(false);

  const stats: Array<{key: 'statsActiveProjects' | 'statsOpenTasks' | 'statsDoneThisWeek'; value: number}> = [
    {key: 'statsActiveProjects', value: 4},
    {key: 'statsOpenTasks', value: TASKS_TOTAL - TASKS_DONE},
    {key: 'statsDoneThisWeek', value: TASKS_DONE},
  ];

  return (
    <div style={{maxWidth: 720, margin: '0 auto', padding: 24, display: 'flex', flexDirection: 'column', gap: 20}}>
      <header style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 16, flexWrap: 'wrap'}}>
        <div>
          <Text variant="header-1">{t('appTitle')}</Text>
          <div>
            <Text variant="body-2" color="secondary">
              {t('appSubtitle')}
            </Text>
          </div>
        </div>
        <LanguageSwitcher />
      </header>

      <section>
        <Text variant="subheader-2">{t('greeting', {name: USER_NAME})}</Text>
        <div>
          <Text variant="body-1" color="secondary">
            {t('welcomeBack')}
          </Text>
        </div>
      </section>

      <section style={{display: 'flex', gap: 12, flexWrap: 'wrap'}}>
        {stats.map(({key, value}) => (
          <Card key={key} style={{flex: '1 1 160px', padding: 16}}>
            <Text variant="display-2">{value}</Text>
            <div>
              <Text variant="body-2" color="secondary">
                {t(key)}
              </Text>
            </div>
          </Card>
        ))}
      </section>

      <Card style={{padding: 16}}>
        <Text variant="subheader-2">{t('progressTitle')}</Text>
        <div style={{margin: '12px 0 8px'}}>
          <Progress value={Math.round((TASKS_DONE / TASKS_TOTAL) * 100)} />
        </div>
        <Text variant="body-2" color="secondary">
          {t('progressValue', {done: TASKS_DONE, total: TASKS_TOTAL})}
        </Text>
      </Card>

      <Card style={{padding: 16, display: 'flex', flexDirection: 'column', gap: 8}}>
        <Text variant="subheader-2">{t('notificationsTitle')}</Text>
        {notificationsRead ? (
          <Text variant="body-2" color="secondary">
            {t('notificationsEmpty')}
          </Text>
        ) : (
          <>
            <Text variant="body-2">{t('notificationReview', {name: 'Ivan'})}</Text>
            <Text variant="body-2">{t('notificationDeploy')}</Text>
            <div>
              <Button view="flat" size="m" onClick={() => setNotificationsRead(true)}>
                {t('markAllRead')}
              </Button>
            </div>
          </>
        )}
      </Card>

      <footer style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
        <Text variant="caption-2" color="secondary">
          {t('footerNote')}
        </Text>
        <Button view="action">{t('createTask')}</Button>
      </footer>
    </div>
  );
}

